static int cow_write(off_t a, char *buf, size_t len, CLIENT *client, int fua) {
	pthread_mutex_lock(&client->diff_lock);
	if (diff_open(client)) {
		pthread_mutex_unlock(&client->diff_lock);
		return -1;
	}
	while (len > 0) {
		uint64_t page = a / DIFFPAGESIZE;
		off_t pagestart = (off_t)page * DIFFPAGESIZE;
		size_t chunk = pagestart + DIFFPAGESIZE - a;  // bytes remaining in this page
		if (chunk > len) chunk = len;

		off_t diff_off;
		if (diff_page_alloc(client, page, &diff_off))  // with skip-copy optimization param
			goto err;
		if (pwrite_loop(client->difffile, buf, chunk, diff_off + (a - pagestart)))
			goto err;
		a += chunk; buf += chunk; len -= chunk;
	}
	if (client->server->flags & F_SYNC) {
		if (fsync(client->difffile) < 0) goto err;
	} else if (fua) {
		if (fdatasync(client->difffile) < 0) goto err;
	}
	pthread_mutex_unlock(&client->diff_lock);
	return 0;
err:
	pthread_mutex_unlock(&client->diff_lock);
	return -1;
}
