void daemonize() {
        pid_t child=fork();
        if(child < 0) {
		err("fork");
	} else if(child > 0) {
                exit(EXIT_SUCCESS);
	} else {
                if(setsid() < 0) {
                        err("setsid");
                }
        }
        if(chdir("/")<0) {
                err("chdir");
        }
	if(!*pidfname) {
		strncpy(pidfname, "/var/run/nbd-server.pid", 255);
	}
