/**
 * Write data to the copy-on-write diff file instead of to the exported
 * file itself.
 *
 * Data is tracked in chunks of DIFFPAGESIZE bytes. When a page is
 * written to for the first time, it is allocated in the diff file;
 * unless the write covers the whole page, the page is pre-filled with
 * the data from the exported file, so that the unwritten parts of the
 * page retain their original content.
 *
 * @param client the client we're serving
 * @param masterfd filedescriptor of the exported file
 * @param masteroff offset in the exported file matching offset a
 * @param a the offset in the export where the write starts
 * @param buf the data to write
 * @param len length of the data
 * @param fua whether to force unit access
 * @return number of bytes written (i.e., len) on success, -1 on error
 */
static ssize_t cow_write(CLIENT *client, int masterfd, off_t masteroff, off_t a, char *buf, size_t len, int fua) {
	size_t done = 0;

	pthread_mutex_lock(&client->diff_lock);
	if (client->difffile == -1 && diff_file_create(client)) {
		pthread_mutex_unlock(&client->diff_lock);
		return -1;
	}
	while (done < len) {
		off_t cur = a + done;
		off_t pagenum = cur / DIFFPAGESIZE;
		off_t pagestart = pagenum * DIFFPAGESIZE;
		off_t pageoff = cur - pagestart;
		size_t chunk = DIFFPAGESIZE - pageoff;
		if (chunk > len - done)
			chunk = len - done;

		off_t diffoff;
		gint64 *val = g_hash_table_lookup(client->difmap, &pagenum);
		if (val) {
			diffoff = *val;
		} else {
			/* allocate the page in the diff file */
			if (client->server->flags & F_SPARSE)
				diffoff = pagestart;
			else
				diffoff = client->difffilelen;

			if (pageoff != 0 || chunk < DIFFPAGESIZE) {
				/* partial page write: pre-fill the page with
				 * the data from the exported file so that the
				 * data it already contains is preserved. Note
				 * the final page of the export may be shorter
				 * than DIFFPAGESIZE. */
				char page[DIFFPAGESIZE];
				size_t plen = DIFFPAGESIZE;
				if (pagestart + (off_t)plen > (off_t)client->exportsize)
					plen = client->exportsize - pagestart;
				memset(page, 0, sizeof(page));
				if (read_fully(masterfd, page, plen, masteroff + (pagestart - a)) < 0)
					goto err;
				if (write_fully(client->difffile, page, plen, diffoff) < 0)
					goto err;
			}
			gint64 *key = g_new(gint64, 1);
			gint64 *newval = g_new(gint64, 1);
			*key = pagenum;
			*newval = diffoff;
			g_hash_table_replace(client->difmap, key, newval);
			if (!(client->server->flags & F_SPARSE))
				client->difffilelen += DIFFPAGESIZE;
		}
		if (write_fully(client->difffile, buf + done, chunk, diffoff + pageoff) < 0)
			goto err;
		done += chunk;
	}
	if (client->server->flags & F_SYNC) {
		if (fsync(client->difffile) < 0)
			goto err;
	} else if (fua) {
		if (fdatasync(client->difffile) < 0)
			goto err;
	}
	pthread_mutex_unlock(&client->diff_lock);
	return done;
err:
	pthread_mutex_unlock(&client->diff_lock);
	return -1;
}
```

