 /**
+ * Read an amount of bytes at a given offset from a file, retrying on
+ * partial reads.
+ *
+ * @param fd The filedescriptor to read from
+ * @param buf The buffer to read into
+ * @param len The size of buf
+ * @param off The offset where the read should start
+ * @return 0 on success, -1 on failure
+ **/
+static int pread_fully(int fd, char *buf, size_t len, off_t off) {
+	while(len > 0) {
+		ssize_t ret = pread(fd, buf, len, off);
+		if(ret <= 0)
+			return -1;
+		buf += ret;
+		off += ret;
+		len -= ret;
+	}
+	return 0;
+}
+
+/**
+ * Write an amount of bytes at a given offset to a file, retrying on
+ * partial writes.
+ *
+ * @param fd The filedescriptor to write to
+ * @param buf The buffer to write from
+ * @param len The size of buf
+ * @param off The offset where the write should start
+ * @return 0 on success, -1 on failure
+ **/
+static int pwrite_fully(int fd, const char *buf, size_t len, off_t off) {
+	while(len > 0) {
+		ssize_t ret = pwrite(fd, buf, len, off);
+		if(ret <= 0)
+			return -1;
+		buf += ret;
+		off += ret;
+		len -= ret;
+	}
+	return 0;
+}
