+
+		val = g_hash_table_lookup(client->difmap, &pagenum);
+		if(val) {
+			diffoff = (off_t)*val;
+		} else {
+			gint64 *key, *newval;
+
+			if(client->server->flags & F_SPARSE)
+				diffoff = pagestart;
+			else
+				diffoff = client->difffilelen;
+
+			if(pageoff != 0 || chunk < DIFFPAGESIZE) {
+				/* only part of the page is written; pre-fill
+				 * it with the data from the exported file.
+				 * Note that the last page of the export may
+				 * be shorter than DIFFPAGESIZE. */
+				char page[DIFFPAGESIZE];
+				size_t plen = DIFFPAGESIZE;
+
+				if((uint64_t)pagestart + plen > client->exportsize)
+					plen = client->exportsize - pagestart;
+				memset(page, 0, sizeof(page));
+				if(pread_fully(masterfd, page, plen, masteroff + (pagestart - a)))
