+		else
+			ret = pread(masterfd, buf + done, chunk, masteroff + done);
+		if(ret <= 0)
+			return ret;
+		done += ret;
+	}
+	return done;
+}
+
+/**
+ * Clean up the copy-on-write state of a client.
+ *
+ * The diff file is removed and all associated resources are freed. The
+ * exported file itself is left untouched, so all writes done during the
+ * connection are discarded.
+ *
+ * @param client the client whose copy-on-write state should be cleaned up
+ **/
